describe('Checkout Form - Card Expiry Validation', () => {
    beforeEach(() => {
        cy.visit('/checkout');
    });

    it('should accept a valid card expiry date in MM/YY format', () => {
        cy.get('input[name="cardExpiry"]').type('12/25');
        cy.get('form').submit();
        cy.get('.success-message').should('be.visible').and('contain', 'Payment processed successfully');
    });

    it('should show an error message for an invalid card expiry date', () => {
        cy.get('input[name="cardExpiry"]').type('13/25'); // Invalid month
        cy.get('form').submit();
        cy.get('.error-message').should('be.visible').and('contain', 'Please enter a valid expiry date in MM/YY format');
    });
});
